"""The frozen corpus in vectors/, generated by tools/vectorgen.py from the oracle.

Each test walks one whole file and reports the first few disagreements, so a
regression reads as a short diff instead of thousands of failing items.
"""

from __future__ import annotations

from pathlib import Path

import pytest

import brd14
from brd14 import ErrorCode, InvalidIdError

from support import locate_vectors, read_tsv, unhex


def _report(failures: list[str], total: int) -> None:
    if failures:
        pytest.fail(f"{len(failures)} of {total} rows disagree; first:\n  " + "\n  ".join(failures[:20]))


def test_valid() -> None:
    rows = read_tsv("valid.tsv")
    assert len(rows) >= 4096, "the bench corpus is the first 4096 rows"
    failures = []
    for ns, snow_s, id_, h, ms, ts, node, seq in rows:
        snow = int(snow_s)
        got = (
            brd14.encode(ns, snow),
            brd14.decode(id_),
            brd14.decode(id_.encode("ascii")),
            brd14.hash32(snow),
            brd14.unix_ms(snow),
            (brd14.ts_of(snow), brd14.node_of(snow), brd14.seq_of(snow)),
            brd14.check(id_),
            brd14.is_valid(id_),
            brd14.is_valid(id_.encode("ascii")),
        )
        want = (
            id_,
            (ns, snow),
            (ns, snow),
            int(h),
            int(ms),
            (int(ts), int(node), int(seq)),
            ErrorCode.OK,
            True,
            True,
        )
        b = brd14.parse(id_)
        if got != want or (b.ns, b.snow, b.ts, b.node, b.seq, b.unix_ms) != (
            ns, snow, int(ts), int(node), int(seq), int(ms)
        ) or str(b) != id_:
            failures.append(f"{id_}: got {got!r}")
    _report(failures, len(rows))


def test_invalid() -> None:
    rows = read_tsv("invalid.tsv")
    assert rows
    failures = []
    for id_hex, cls in rows:
        raw = unhex(id_hex)
        want = ErrorCode[cls]
        views: list[str | bytes] = [raw]
        try:
            views.append(raw.decode("utf-8", "surrogatepass"))
        except UnicodeDecodeError:
            pass
        for view in views:
            try:
                brd14.decode(view)
            except InvalidIdError as e:
                got = e.code
            else:
                got = ErrorCode.OK
            if got is not want or brd14.check(view) is not want or brd14.is_valid(view):
                failures.append(f"{view!r}: want {cls}, got {got.name} / check {brd14.check(view).name}")
    _report(failures, len(rows))


def test_encode_invalid() -> None:
    rows = read_tsv("encode_invalid.tsv")
    assert rows
    failures = []
    for ns_hex, snow_s, cls in rows:
        # surrogateescape keeps every byte; a non-ASCII byte can never pass as A-Z.
        ns = unhex(ns_hex).decode("utf-8", "surrogateescape")
        try:
            brd14.encode(ns, int(snow_s))
        except InvalidIdError as e:
            if e.code is not ErrorCode[cls]:
                failures.append(f"encode({ns!r}, {snow_s}): want {cls}, got {e.code.name}")
        else:
            failures.append(f"encode({ns!r}, {snow_s}): want {cls}, got OK")
    _report(failures, len(rows))


def test_node() -> None:
    rows = read_tsv("node.tsv")
    assert rows
    failures = []
    for host_hex, pid, node in rows:
        host = unhex(host_hex)
        if brd14.node_from(host, int(pid)) != int(node):
            failures.append(f"node_from({host!r}, {pid}) != {node}")
        try:
            as_str = host.decode("utf-8", "surrogatepass")
        except UnicodeDecodeError:
            continue
        if brd14.node_from(as_str, int(pid)) != int(node):
            failures.append(f"node_from({as_str!r}, {pid}) != {node}")
    _report(failures, len(rows))


def test_missing_vectors_skip(tmp_path: Path) -> None:
    with pytest.raises(pytest.skip.Exception):
        locate_vectors(tmp_path / "nope", {})


def test_missing_vectors_fail_when_required(tmp_path: Path) -> None:
    with pytest.raises(pytest.fail.Exception):
        locate_vectors(tmp_path / "nope", {"BRD14_REQUIRE_VECTORS": "1"})
